import { mkdir, readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import path from "node:path";

const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const pagePath = path.join(repoRoot, "dashboard", "src", "index.js");
const outputPath = path.join(repoRoot, "dashboard", "dist", "index.js");

const pageSource = await readFile(pagePath, "utf8");

const banner = [
  "/**",
  " * Generated by `npm run build:dashboard`.",
  " */",
  "",
].join("\n");

await mkdir(path.dirname(outputPath), { recursive: true });
await writeFile(outputPath, `${banner}${pageSource.trim()}\n`, "utf8");
